private _isCellMetadataChanged(a: NotebookCellMetadata, b: NotebookCellMetadata) {
	const keys = new Set([...Object.keys(a || {}), ...Object.keys(b || {})]);
	for (const key of keys) {
		if (
			(a[key as keyof NotebookCellMetadata] !== b[key as keyof NotebookCellMetadata])
			&&
			!(this.transientOptions.transientCellMetadata[key as keyof NotebookCellMetadata])
		) {
			return true;
		}
	}

	return false;
}

private _changeCellMetadata(cell: NotebookCellTextModel, metadata: NotebookCellMetadata, computeUndoRedo: boolean, beginSelectionState: ISelectionState | undefined, undoRedoGroup: UndoRedoGroup | undefined) {
	const triggerDirtyChange = this._isCellMetadataChanged(cell.metadata, metadata);

	if (triggerDirtyChange) {
		if (computeUndoRedo) {
			const index = this._cells.indexOf(cell);
			this._operationManager.pushEditOperation(new CellMetadataEdit(this.uri, index, Object.freeze(cell.metadata), Object.freeze(metadata), {
				updateCellMetadata: (index, newMetadata) => {
					const cell = this._cells[index];
					if (!cell) {
						return;
					}
					this._changeCellMetadata(cell, newMetadata, false, beginSelectionState, undoRedoGroup);
				}
			}), beginSelectionState, undefined, this._alternativeVersionId, undoRedoGroup);
		}
	}

	// should be deferred
	cell.metadata = metadata;
	this._pauseableEmitter.fire({
		rawEvents: [{ kind: NotebookCellsChangeType.ChangeCellMetadata, index: this._cells.indexOf(cell), metadata: cell.metadata, transient: !triggerDirtyChange }],
		versionId: this.versionId,
		synchronous: true,
		endSelectionState: undefined
	});
}

export class CellMetadataEdit implements IResourceUndoRedoElement {
	type: UndoRedoElementType.Resource = UndoRedoElementType.Resource;
	label: string = 'Update Cell Metadata';
	code: string = 'undoredo.textBufferEdit';
	constructor(
		public resource: URI,
		readonly index: number,
		readonly oldMetadata: NotebookCellMetadata,
		readonly newMetadata: NotebookCellMetadata,
		private editingDelegate: ITextCellEditingDelegate,
	) {

	}

	undo(): void {
		if (!this.editingDelegate.updateCellMetadata) {
			return;
		}

		this.editingDelegate.updateCellMetadata(this.index, this.oldMetadata);
	}

	redo(): void | Promise<void> {
		if (!this.editingDelegate.updateCellMetadata) {
			return;
		}

		this.editingDelegate.updateCellMetadata(this.index, this.newMetadata);
	}
}

		this._register(RedoCommand.addImplementation(PRIORITY, 'notebook-undo-redo', () => {
			const editor = getNotebookEditorFromEditorPane(this._editorService.activeEditorPane);
			const viewModel = editor?.getViewModel() as NotebookViewModel | undefined;

			if (editor && editor.hasEditorFocus() && editor.hasModel() && viewModel) {
				return viewModel.redo().then(cellResources => {
					if (cellResources?.length) {
						for (let i = 0; i < editor.getLength(); i++) {
							const cell = editor.cellAt(i);
							if (cell.cellKind === CellKind.Markup && cellResources.find(resource => resource.fragment === cell.model.uri.fragment)) {
								cell.updateEditState(CellEditState.Editing, 'redo');
							}
						}

						editor?.setOptions({ cellOptions: { resource: cellResources[0] }, preserveFocus: true });
					}
				});
			}

			return false;
		}));
	}
}

async redo() {

	const editStack = this._undoService.getElements(this.uri);
	const element = editStack.future[0];

	if (element && element instanceof SingleModelEditStackElement || element instanceof MultiModelEditStackElement) {
		await this._withElement(element, async () => {
			await this._undoService.redo(this.uri);
		});

		return (element instanceof SingleModelEditStackElement) ? [element.resource] : element.resources;
	}

	await this._undoService.redo(this.uri);

	return [];
}

async perform(reason?: TextModelEditSource): Promise<readonly URI[]> {

	if (this._edits.length === 0) {
		return [];
	}

	const ranges: number[] = [1];
	for (let i = 1; i < this._edits.length; i++) {
		if (Object.getPrototypeOf(this._edits[i - 1]) === Object.getPrototypeOf(this._edits[i])) {
			ranges[ranges.length - 1]++;
		} else {
			ranges.push(1);
		}
	}

	// Show infinte progress when there is only 1 item since we do not know how long it takes
	const increment = this._edits.length > 1 ? 0 : undefined;
	this._progress.report({ increment, total: 100 });
	// Increment by percentage points since progress API expects that
	const progress: IProgress<void> = { report: _ => this._progress.report({ increment: 100 / this._edits.length }) };

	const resources: (readonly URI[])[] = [];
	let index = 0;
	for (const range of ranges) {
		if (this._token.isCancellationRequested) {
			break;
		}
		const group = this._edits.slice(index, index + range);
		if (group[0] instanceof ResourceFileEdit) {
			resources.push(await this._performFileEdits(<ResourceFileEdit[]>group, this._undoRedoGroup, this._undoRedoSource, this._confirmBeforeUndo, progress));
		} else if (group[0] instanceof ResourceTextEdit) {
			resources.push(await this._performTextEdits(<ResourceTextEdit[]>group, this._undoRedoGroup, this._undoRedoSource, progress, reason));
		} else if (group[0] instanceof ResourceNotebookCellEdit) {
			resources.push(await this._performCellEdits(<ResourceNotebookCellEdit[]>group, this._undoRedoGroup, this._undoRedoSource, progress));
		} else if (group[0] instanceof ResourceAttachmentEdit) {
			resources.push(await this._performOpaqueEdits(<ResourceAttachmentEdit[]>group, this._undoRedoGroup, this._undoRedoSource, progress));
		} else {
			console.log('UNKNOWN EDIT');
		}
		index = index + range;
	}

	return resources.flat();
